/**
 * @vitest-environment jsdom
 */
import { createSSRApp, h, useCssVars } from '@vue/runtime-dom'
import { expect } from 'vitest'

describe('tmp 11739', () => {
  test('css var with dot + child style object', () => {
    const container = document.createElement('div')
    container.innerHTML = `<div style="--data-v-test-props\\.backgroundColor:blue;display:flex;"></div>`
    const Child = {
      setup() {
        return () => h('div', { style: { display: 'flex' } })
      },
    }
    const app = createSSRApp({
      setup() {
        useCssVars(() => ({
          'data-v-test-props.backgroundColor': 'blue',
        }))
        return () => h(Child)
      },
    })
    app.mount(container)
    expect(`Hydration style mismatch`).not.toHaveBeenWarned()
  })

  test('css var with dot + child style string', () => {
    const container = document.createElement('div')
    container.innerHTML = `<div style="--data-v-test-props\\.padding:20px;padding:4px;"></div>`
    const Child = {
      setup() {
        return () => h('div', { style: 'padding: 4px' })
      },
    }
    const app = createSSRApp({
      setup() {
        useCssVars(() => ({
          'data-v-test-props.padding': '20px',
        }))
        return () => h(Child)
      },
    })
    app.mount(container)
    expect(`Hydration style mismatch`).not.toHaveBeenWarned()
  })
})

